60	     * Adds a claim for the person; a missing date takes the sheet's today. Refused when dated in a closed period or
61	     * after the person's retirement date, and a correction (a negative amount) unless it corrects a settled claim of
62	     * the person.
63	     */
64	    @Transactional
65	    public Claim add(String by, String sheetId, Long personId, BigDecimal amount, LocalDate date, String note,
66	            String corrects) {
67	        LocalDate on = dateOrToday(sheetId, date);
68	        refuseInClosedPeriod(sheetId, on);
69	        RollupService.Snapshot before = rollup.snapshot(sheetId);
70	        Person person = person(sheetId, personId);
71	        refuseAfterRetirement(person, on);
72	        String corrected = correctedNumber(sheetId, personId, amount, corrects);
73	        Claim claim = new Claim(sheetId, personId, scaled(amount), on, noteOf(note));
74	        claim.setCorrects(corrected);
75	        claim.setRoundsOn(roundsOn(sheetId, corrected, on));
76	        claim.setDueBy(on.plusDays(sheets.load(sheetId).termsFor(person.gradeOn(on), on)));
77	        logStatus(by, sheetId, person, claim);
78	        Claim added = claims.saveAndFlush(claim);
79	        audit.recordOnCommit(record("CLAIM_ADDED", by, person, added));
80	        rollup.recordChanges(by, sheetId, before);
81	        return added;
82	    }
