84	    /**
85	     * Edits a claim; refused unless it is a draft, when it is dated in a closed period, or when the edit would date
86	     * it in one. An open claim is changed by voiding it and adding a new one.
87	     */
88	    @Transactional
89	    public Claim update(String by, String sheetId, Long id, BigDecimal amount, LocalDate date, String note,
90	            String corrects) {
91	        LocalDate on = dateOrToday(sheetId, date);
92	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
93	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
94	        if (claim.getStatus() != ClaimStatus.DRAFT) {
95	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft claim can be edited.");
96	        }
97	        refuseInClosedPeriod(sheetId, claim.getDate());
98	        refuseInClosedPeriod(sheetId, on);
99	        refuseAfterRetirement(person(sheetId, claim.getPersonId()), on);
100	        String corrected = correctedNumber(sheetId, claim.getPersonId(), amount, corrects);
101	        RollupService.Snapshot before = rollup.snapshot(sheetId);
102	        claim.setAmount(scaled(amount));
103	        claim.setCorrects(corrected);
104	        claim.setDate(on);
105	        claim.setRoundsOn(roundsOn(sheetId, corrected, on));
106	        claim.setNote(noteOf(note));
107	        Claim saved = claims.saveAndFlush(claim);
108	        audit.recordOnCommit(record("CLAIM_EDITED", by, person(sheetId, saved.getPersonId()), saved));
109	        rollup.recordChanges(by, sheetId, before);
110	        return saved;
111	    }
