113	    /**
114	     * Moves the claim to the status; a change its status does not allow is refused, as is settling by the user
115	     * who opened it, and any change to a claim dated in a closed period. A clerk settling a claim whose due is above
116	     * the clerk limit makes it PENDING instead, for a steward to approve or reject.
117	     */
118	    @Transactional
119	    public Claim changeStatus(String by, String sheetId, Long id, ClaimStatus next) {
120	        Claim claim = lockedClaim(sheetId, id);
121	        RollupService.Snapshot before = rollup.snapshot(sheetId);
122	        // settling is the step from OPEN; a pending claim is settled by approving it
123	        if (!claim.getStatus().canMoveTo(next) || next == ClaimStatus.PENDING
124	                || (next == ClaimStatus.SETTLED && claim.getStatus() != ClaimStatus.OPEN)
125	                || (next == ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.DRAFT)) {
126	            throw new ResponseStatusException(HttpStatus.CONFLICT,
127	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
128	        }
129	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.load(sheetId).getToday())) {
130	            throw new ResponseStatusException(HttpStatus.CONFLICT,
131	                    "The claim is deferred until " + claim.getDeferredUntil() + ".");
132	        }
133	        if (next == ClaimStatus.SETTLED && by.equals(claim.getOpenedBy())) {
134	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The user who opened a claim cannot settle it.");
135	        }
136	        if (next == ClaimStatus.OPEN) {
137	            number(sheetId, claim);
138	            claim.setOpenedBy(by);
139	        }
140	        Person person = person(sheetId, claim.getPersonId());
141	        String event = switch (next) {
142	            case OPEN -> "CLAIM_OPENED";
143	            case SETTLED -> "CLAIM_SETTLED";
144	            case VOID -> "CLAIM_VOIDED";
145	            case DRAFT, PENDING -> throw new IllegalStateException();
146	        };
147	        String tail = "";
148	        if (next == ClaimStatus.SETTLED) {
149	            // the due is fixed at the figure a statement bound it to, else at the rate the person's grade has in
150	            // force on the claim's date, with the late charge it has gained by today; with none it stays live
151	            BigDecimal figure = claim.isStated() && claim.getStatedDue() != null ? claim.getStatedDue()
152	                    : liveDue(sheetId, person, claim);
153	            BigDecimal fixed = claim.isCorrection() ? figure
154	                    : withLateCharge(figure, claim, sheets.load(sheetId));
155	            if (settings.aboveClerkLimit(sheetId, by, fixed)) {
156	                next = ClaimStatus.PENDING;
157	                event = "CLAIM_PENDING";
158	            } else {
159	                claim.setSettledDue(fixed);
160	                tail = " due=" + (fixed == null ? "n/a" : fixed.toPlainString());
161	            }
162	        }
163	        claim.setStatus(next);
164	        logStatus(by, sheetId, person, claim);
165	        Claim saved = claims.saveAndFlush(claim);
166	        audit.recordOnCommit(record(event, by, person, saved) + tail);
167	        rollup.recordChanges(by, sheetId, before);
168	        return saved;
169	    }
