171	    /**
172	     * Defers an OPEN claim until a date after the sheet's today: until the sheet's today reaches it the claim counts
173	     * in no total, is not overdue, cannot be settled and is left unbound by a statement. Refused for a claim that is
174	     * not OPEN, a date not after today, and in a closed period.
175	     */
176	    @Transactional
177	    public Claim defer(String by, String sheetId, Long id, LocalDate until) {
178	        Claim claim = lockedClaim(sheetId, id);
179	        if (claim.getStatus() != ClaimStatus.OPEN) {
180	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only an OPEN claim can be deferred.");
181	        }
182	        LocalDate today = sheets.load(sheetId).getToday();
183	        if (until == null || (today != null && !until.isAfter(today))) {
184	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
185	                    "A claim can only be deferred to a date after the sheet's today.");
186	        }
187	        RollupService.Snapshot before = rollup.snapshot(sheetId);
188	        claim.setDeferredUntil(until);
189	        Claim saved = claims.saveAndFlush(claim);
190	        audit.recordOnCommit(record("CLAIM_DEFERRED", by, person(sheetId, saved.getPersonId()), saved) + " until="
191	                + until);
192	        rollup.recordChanges(by, sheetId, before);
193	        return saved;
194	    }
195	
196	    /**
197	     * A steward approves a pending claim: it is settled, its due fixed at the live figure it shows now. Refused
198	     * unless it is pending, unless the user is a steward, for the user who opened it, and in a closed period.
199	     */
200	    @Transactional
201	    public Claim approve(String by, String sheetId, Long id) {
202	        Claim claim = pendingClaim(by, sheetId, id);
203	        if (by.equals(claim.getOpenedBy())) {
204	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The user who opened a claim cannot approve it.");
205	        }
206	        RollupService.Snapshot before = rollup.snapshot(sheetId);
207	        Person person = person(sheetId, claim.getPersonId());
208	        BigDecimal fixed = due(sheetId, person, claim);
209	        claim.setSettledDue(fixed);
210	        claim.setStatus(ClaimStatus.SETTLED);
211	        logStatus(by, sheetId, person, claim);
212	        Claim saved = claims.saveAndFlush(claim);
213	        audit.recordOnCommit(record("CLAIM_APPROVED", by, person, saved) + " due="
214	                + (fixed == null ? "n/a" : fixed.toPlainString()));
215	        rollup.recordChanges(by, sheetId, before);
216	        return saved;
217	    }
218	
219	    /**
220	     * A steward re-settles a settled claim: its due is frozen again at the figure it would have today as an open
221	     * claim bound by no statement (today's rates, grades and floor, with the late charge it has gained by today; a
222	     * correction gains none). Refused unless the user is a steward, unless it is settled, and in a closed period.
223	     */
224	    @Transactional
225	    public Claim resettle(String by, String sheetId, Long id) {
226	        if (!settings.isSteward(sheetId, by)) {
227	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-settle a claim.");
228	        }
229	        Claim claim = lockedClaim(sheetId, id);
230	        if (claim.getStatus() != ClaimStatus.SETTLED) {
231	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a SETTLED claim can be re-settled.");
232	        }
233	        RollupService.Snapshot before = rollup.snapshot(sheetId);
234	        Person person = person(sheetId, claim.getPersonId());
235	        BigDecimal old = claim.getSettledDue();
236	        BigDecimal live = liveDue(sheetId, person, claim);
237	        BigDecimal fixed = claim.isCorrection() ? live : withLateCharge(live, claim, sheets.load(sheetId));
238	        claim.setSettledDue(fixed);
239	        logStatus(by, sheetId, person, claim);
240	        Claim saved = claims.saveAndFlush(claim);
241	        audit.recordOnCommit(record("CLAIM_RESETTLED", by, person, saved) + " old=" + text(old) + " new="
242	                + text(fixed));
243	        rollup.recordChanges(by, sheetId, before);
244	        return saved;
245	    }
246	
247	    /**
248	     * A steward rejects a pending claim with a reason: it is open again, bound again by its person's last statement
249	     * when that included it. Refused unless it is pending, unless the user is a steward, without a reason, and in a
250	     * closed period.
251	     */
252	    @Transactional
253	    public Claim reject(String by, String sheetId, Long id, String reason) {
254	        String why = reason == null ? "" : reason.strip();
255	        if (why.isEmpty()) {
256	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A rejection needs a reason.");
257	        }
258	        Claim claim = pendingClaim(by, sheetId, id);
259	        RollupService.Snapshot before = rollup.snapshot(sheetId);
260	        claim.setStatus(ClaimStatus.OPEN);
261	        logStatus(by, sheetId, person(sheetId, claim.getPersonId()), claim);
262	        Claim saved = claims.saveAndFlush(claim);
263	        audit.recordOnCommit(record("CLAIM_REJECTED", by, person(sheetId, saved.getPersonId()), saved)
264	                + " reason=" + why);
265	        rollup.recordChanges(by, sheetId, before);
266	        return saved;
267	    }
268	
269	    /**
270	     * A steward moves a DRAFT, OPEN or PENDING claim to another person of the sheet. It keeps its number and date,
271	     * loses any figure a statement bound it to (it is live again until its new person's next statement), and is
272	     * listed as its new person's newest claim. Refused unless the user is a steward, for a settled or voided claim,
273	     * to the person it is already with, in a closed period, and when it is dated after the new person's retirement.
274	     */
275	    @Transactional
276	    public Claim reassign(String by, String sheetId, Long id, Long toPersonId) {
277	        if (!settings.isSteward(sheetId, by)) {
278	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can move a claim.");
279	        }
280	        Claim claim = lockedClaim(sheetId, id);
281	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
282	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A " + claim.getStatus() + " claim cannot move.");
283	        }
284	        if (claim.getPersonId().equals(toPersonId)) {
285	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already that person's.");
286	        }
287	        Person from = person(sheetId, claim.getPersonId());
288	        Person to = person(sheetId, toPersonId);
289	        refuseAfterRetirement(to, claim.getDate());
290	        RollupService.Snapshot before = rollup.snapshot(sheetId);
291	        claim.setPersonId(to.getId());
292	        claim.unbind();
293	        Claim saved = claims.saveAndFlush(claim);
294	        claims.relist(saved.getId());
295	        audit.recordOnCommit(record("CLAIM_REASSIGNED", by, to, saved) + " from=" + from.getName() + " to="
296	                + to.getName());
297	        rollup.recordChanges(by, sheetId, before);
298	        return saved;
299	    }
