301	    /** Logs the status the claim now has: by the user, on the sheet's today, at the due it shows now. */
302	    private void logStatus(String by, String sheetId, Person person, Claim claim) {
303	        claim.logStatus(by, sheets.load(sheetId).getToday(), due(sheetId, person, claim));
304	    }
305	
306	    /** The pending claim, locked, for a steward to decide; refused otherwise. */
307	    private Claim pendingClaim(String by, String sheetId, Long id) {
308	        Claim claim = lockedClaim(sheetId, id);
309	        if (claim.getStatus() != ClaimStatus.PENDING) {
310	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a PENDING claim can be approved or rejected.");
311	        }
312	        if (!settings.isSteward(sheetId, by)) {
313	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can approve or reject a claim.");
314	        }
315	        return claim;
316	    }
317	
318	    /** The claim, locked; refused when it is dated in a closed period. */
319	    private Claim lockedClaim(String sheetId, Long id) {
320	        // the sheet is locked before the claim, in the order a period closing takes them
321	        sheets.lock(sheetId);
322	        Claim claim = claims.findWithLockByIdAndSheetId(id, sheetId)
323	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
324	        refuseInClosedPeriod(sheetId, claim.getDate());
325	        return claim;
326	    }
327	
328	    /**
329	     * Gives the claim being opened its number: while the sheet's period numbering from is set and its today is on or
330	     * after it, the next in the sequence of the period the claim is dated in (X for none), else the sheet's next.
331	     * The sheet is locked, so two claims opened at once never get the same one.
332	     */
333	    private void number(String sheetId, Claim claim) {
334	        Sheet sheet = sheets.load(sheetId);
335	        LocalDate from = sheet.getPeriodNumberingFrom();
336	        if (from == null || sheet.getToday().isBefore(from)) {
337	            claim.setNumber(String.valueOf(sheets.nextClaimNumber(sheetId)));
338	            return;
339	        }
340	        String sequence = periods.findFirstBySheetIdAndFromLessThanEqualAndToGreaterThanEqual(sheetId,
341	                claim.getDate(), claim.getDate()).map(Period::getName).orElse(NO_PERIOD);
342	        Long last = claims.lastInSequence(sheetId, sequence);
343	        claim.numberIn(sequence, last == null ? 1 : last + 1);
344	    }
345	
346	    /**
347	     * The claim's live due: at the rate its person's grade in force on its date has in force on that date, and at least the sheet's
348	     * floor in force on its date (a correction has none), rounded as the sheet's policy date decides for it; null (n/a) with none.
349	     */
350	    public BigDecimal liveDue(String sheetId, Person person, Claim claim) {
351	        Sheet sheet = sheets.load(sheetId);
352	        BigDecimal floor = claim.isCorrection() ? null : sheet.floorOn(claim.getDate());
353	        RoundingMode rounding = sheet.roundingOn(claim.getRoundsOn());
354	        return rates.findInForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate()).map(Rate::getPct)
355	                .map(pct -> floored(dueOn(claim.getAmount(), pct, rounding), floor)).orElse(null);
356	    }
357	
358	    /**
359	     * The figure the claim shows and totals: its settled due, else the one a statement bound it to (not while it is
360	     * pending), else live.
361	     */
362	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
363	        if (claim.getSettledDue() != null) {
364	            return claim.getSettledDue();
365	        }
366	        return claim.isBound() ? claim.getStatedDue() : liveDue(sheetId, person, claim);
367	    }
368	
369	    /**
370	     * The due the claim shows and totals: its figure, with the late charge an open (or pending) overdue claim has gained; a
371	     * correction gains none.
372	     */
373	    public BigDecimal due(String sheetId, Person person, Claim claim) {
374	        BigDecimal figure = figure(sheetId, person, claim);
375	        return claim.getStatus().isOpen() && !claim.isCorrection()
376	                ? withLateCharge(figure, claim, sheets.load(sheetId))
377	                : figure;
378	    }
379	
380	    /**
381	     * The figure (null for n/a) of the claim, with the sheet's late percent in force on its date of it added for every full 30 days it is
382	     * overdue (past its due-by) by the sheet's today, rounded like its due; a deferred claim is not overdue. The charge is never bound by a statement: it keeps
383	     * following the sheet's today and its policy date.
384	     */
385	    public static BigDecimal withLateCharge(BigDecimal figure, Claim claim, Sheet sheet) {
386	        if (figure == null || sheet == null || sheet.getToday() == null || claim.isDeferredOn(sheet.getToday())) {
387	            return figure;
388	        }
389	        long overdue = ChronoUnit.DAYS.between(claim.getDueBy(), sheet.getToday());
390	        long periods = overdue > 0 ? overdue / 30 : 0;
391	        BigDecimal latePct = sheet.latePctOn(claim.getDate());
392	        if (periods == 0 || latePct.signum() == 0) {
393	            return figure;
394	        }
395	        return figure.add(dueOn(figure, latePct.multiply(BigDecimal.valueOf(periods)),
396	                sheet.roundingOn(claim.getRoundsOn())));
397	    }
398	
399	    /**
400	     * Refuses a change to a claim dated on the date when a closed period contains it. The sheet stays locked until
401	     * the transaction ends, so a period closing at the same moment is checked in turn.
402	     */
403	    private void refuseInClosedPeriod(String sheetId, LocalDate date) {
404	        sheets.lock(sheetId);
405	        if (periods.existsBySheetIdAndClosedTrueAndFromLessThanEqualAndToGreaterThanEqual(sheetId, date, date)) {
406	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is dated in a closed period.");
407	        }
408	    }
409	
410	    /**
411	     * The number a claim with the amount corrects: for a correction (a negative amount), the number of a settled
412	     * claim of the person, else refused; null for any other claim.
413	     */
414	    private String correctedNumber(String sheetId, Long personId, BigDecimal amount, String corrects) {
415	        if (amount.signum() >= 0) {
416	            return null;
417	        }
418	        corrects = corrects == null ? null : corrects.strip();
419	        if (corrects == null || !claims.existsBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects,
420	                ClaimStatus.SETTLED)) {
421	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
422	                    "A negative amount must correct a settled claim of the person, named by its number.");
423	        }
424	        return corrects;
425	    }
426	
427	    /** Refuses a claim for the person dated after their retirement date; one on or before it is allowed. */
428	    private static void refuseAfterRetirement(Person person, LocalDate date) {
429	        if (person.getRetiredFrom() != null && date.isAfter(person.getRetiredFrom())) {
430	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
431	                    "That claim is dated after the person's retirement.");
432	        }
433	    }
434	
435	    private Person person(String sheetId, Long personId) {
436	        return people.findByIdAndSheetId(personId, sheetId)
437	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
438	    }
439	
440	    /** The audit line about a claim; one that has a number ends with it. */
441	    private static String record(String event, String by, Person person, Claim c) {
442	        String number = c.getNumber();
443	        return event + " sheet=" + c.getSheetId() + " by=" + by + " person=" + person.getName()
444	                + " amount=" + c.getAmount().toPlainString() + " date=" + c.getDate()
445	                + (number != null ? " number=" + number : "");
446	    }
447	
448	    /**
449	     * The due on an amount at a rate: amount times rate divided by 100, rounded to two decimals the given way (a
450	     * negative amount rounds like its positive).
451	     */
452	    public static BigDecimal dueOn(BigDecimal amount, BigDecimal pct, RoundingMode rounding) {
453	        return amount.multiply(pct).movePointLeft(2).setScale(2, rounding);
454	    }
455	
456	    /** The date a claim dated on the date rounds by: that date, or for a correction the corrected claim's date. */
457	    private LocalDate roundsOn(String sheetId, String corrects, LocalDate on) {
458	        return corrects == null ? on
459	                : claims.findBySheetIdAndNumber(sheetId, corrects).map(Claim::getDate).orElse(on);
460	    }
461	
462	    /** The due raised to the floor when it is below it. */
463	    public static BigDecimal floored(BigDecimal due, BigDecimal floor) {
464	        return floor != null && due.compareTo(floor) < 0 ? floor.setScale(2) : due;
465	    }
466	
467	    private LocalDate dateOrToday(String sheetId, LocalDate date) {
468	        return date != null ? date : sheets.load(sheetId).getToday();
469	    }
470	
471	    private static String text(BigDecimal value) {
472	        return value == null ? "n/a" : value.toPlainString();
473	    }
474	
475	    private static BigDecimal scaled(BigDecimal amount) {
476	        return amount.setScale(2, RoundingMode.UNNECESSARY);
477	    }
478	
479	    private static String noteOf(String note) {
480	        return note == null ? "" : note.strip();
481	    }
482	}
