313	export class Claims {
314	  private readonly http = inject(HttpClient);
315	  protected readonly session = inject(Session);
316	  private readonly periods = inject(PeriodStore);
317	  protected readonly settings = inject(SettingsStore);
318	  private readonly rateStore = inject(RateStore);
319	
320	  readonly personId = input.required<number>();
321	  readonly personName = input.required<string>();
322	  readonly claims = input.required<Claim[]>();
323	  // Every grade recorded for the person; a claim's due uses the rate in force on its date for the grade in force then.
324	  readonly grades = input<readonly DatedGrade[]>([]);
325	  // The date the person is retired from; no claim dated after it can be added or saved. Null while not retired.
326	  readonly retiredFrom = input<string | null>(null);
327	  // Every person on the sheet, whom a steward can move a claim to.
328	  readonly people = input<readonly { id: number; name: string }[]>([]);
329	  readonly saved = output<Claim>();
330	  // The claims selected for a bulk action, by id; a checkbox's change is reported, not kept here.
331	  readonly selected = input<ReadonlySet<number>>(new Set());
332	  readonly selectedChange = output<{ id: number; checked: boolean }>();
333	
334	  protected readonly amount = signal('');
335	  protected readonly date = signal('');
336	  protected readonly note = signal('');
337	  protected readonly corrects = signal('');
338	  protected readonly editingId = signal<number | null>(null);
339	  protected readonly error = signal<string | null>(null);
340	  // A submit in flight: a second submit before it answers is ignored, so it stores one claim.
341	  private submitting = false;
342	  // Each claim's refused status change, by claim id.
343	  protected readonly rowErrors = signal<Record<number, string>>({});
344	  // The reason typed to reject each pending claim, by claim id.
345	  protected readonly rejectReasons = signal<Record<number, string>>({});
346	  // The date typed to defer each claim until, by claim id.
347	  protected readonly deferDates = signal<Record<number, string>>({});
348	  // The person (by id) chosen to move each claim to, by claim id.
349	  protected readonly reassignTo = signal<Record<number, string>>({});
350	
351	  protected readonly dueOf = dueOf;
352	
353	  /** Every rate set for the person's grade in force on the date. */
354	  protected ratesOn(date: string): readonly RateView[] {
355	    return this.rateStore.rates().get(gradeOn(this.grades(), date)) ?? [];
356	  }
357	  protected readonly overdue = overdue;
358	  protected readonly deferred = deferred;
359	
360	  protected value(e: Event): string {
361	    return (e.target as HTMLInputElement | HTMLSelectElement).value;
362	  }
363	
364	  protected checked(e: Event): boolean {
365	    return (e.target as HTMLInputElement).checked;
366	  }
367	
368	  /** The name of the period the date falls in; empty when none does. */
369	  protected periodName(date: string): string {
370	    return periodOn(this.periods.list(), date)?.name ?? '';
371	  }
372	
373	  protected edit(c: Claim): void {
374	    this.clearRowError(c.id);
375	    if (c.status !== 'DRAFT') {
376	      // an open claim is changed by voiding it and adding a new one
377	      this.setRowError(c.id, `A ${c.status} claim cannot be edited; only a draft can. Void it and add a new one.`);
378	      return;
379	    }
380	    this.editingId.set(c.id);
381	    this.amount.set(c.amount);
382	    this.date.set(c.date);
383	    this.note.set(c.note);
384	    this.corrects.set(c.corrects ?? '');
385	    this.error.set(null);
386	  }
387	
388	  protected setRejectReason(id: number, reason: string): void {
389	    this.rejectReasons.update((r) => ({ ...r, [id]: reason }));
390	    this.clearRowError(id);
391	  }
392	
393	  protected async act(c: Claim, action: ClaimAction): Promise<void> {
394	    this.clearRowError(c.id);
395	    const sheet = this.session.sheetId();
396	    if (!sheet) return;
397	    const url = `/api/sheets/${encodeURIComponent(sheet)}/claims/${c.id}/${action}`;
398	    if (inClosedPeriod(this.periods.list(), c.date)) {
399	      this.setRowError(c.id, CLOSED);
400	      return;
401	    }
402	    const reason = (this.rejectReasons()[c.id] ?? '').trim();
403	    if (action === 'reject' && !reason) {
404	      this.setRowError(c.id, 'Enter a reason to reject this claim.');
405	      return;
406	    }
407	    try {
408	      const body = action === 'reject' ? { reason } : null;
409	      this.saved.emit(await firstValueFrom(this.http.post<Claim>(url, body)));
410	      if (action === 'reject') this.rejectReasons.update(({ [c.id]: _, ...rest }) => rest);
411	    } catch (e) {
412	      const opener = c.openedBy !== null && c.openedBy === this.session.user();
413	      const forbidden = e instanceof HttpErrorResponse && e.status === 403;
414	      const err =
415	        action === 'settle' && deferred(c, this.session.sheetToday())
416	          ? `This claim is deferred until ${c.deferredUntil}, so it cannot be settled yet.`
417	          : action === 'settle' && opener
418	          ? 'You opened this claim, so another user must settle it.'
419	          : (action === 'approve' || action === 'reject') && forbidden
420	            ? 'Only a steward can approve or reject a pending claim.'
421	            : action === 'resettle' && forbidden
422	              ? 'Only a steward can re-settle a claim.'
423	              : action === 'approve' && opener
424	                ? 'You opened this claim, so another steward must approve it.'
425	                : `A ${c.status} claim cannot be changed that way, or its period is closed.`;
426	      this.setRowError(c.id, err);
427	    }
428	  }
429	
430	  protected setDeferDate(id: number, date: string): void {
431	    this.deferDates.update((d) => ({ ...d, [id]: date }));
432	    this.clearRowError(id);
433	  }
434	
435	  /** Defers an OPEN claim until the typed date, which must be after the sheet's today. */
436	  protected async defer(c: Claim): Promise<void> {
437	    this.clearRowError(c.id);
438	    const sheet = this.session.sheetId();
439	    if (!sheet) return;
440	    const until = (this.deferDates()[c.id] ?? '').trim();
441	    const today = this.session.sheetToday();
442	    if (!/^\d{4}-\d{2}-\d{2}$/.test(until) || (today !== null && until <= today)) {
443	      this.setRowError(c.id, `Enter a date after ${today ?? 'today'} to defer this claim until.`);
444	      return;
445	    }
446	    if (c.status !== 'OPEN') {
447	      this.setRowError(c.id, `A ${c.status} claim cannot be deferred; only an OPEN one can.`);
448	      return;
449	    }
450	    if (inClosedPeriod(this.periods.list(), c.date)) {
451	      this.setRowError(c.id, CLOSED);
452	      return;
453	    }
454	    const url = `/api/sheets/${encodeURIComponent(sheet)}/claims/${c.id}/defer`;
455	    try {
456	      const saved = await firstValueFrom(this.http.post<Claim>(url, { until }));
457	      this.deferDates.update(({ [c.id]: _, ...rest }) => rest);
458	      this.saved.emit(saved);
459	    } catch {
460	      this.setRowError(c.id, `This ${c.status} claim cannot be deferred until ${until}.`);
461	    }
462	  }
463	
464	  protected setReassignTo(id: number, personId: string): void {
465	    this.reassignTo.update((r) => ({ ...r, [id]: personId }));
466	    this.clearRowError(id);
467	  }
468	
469	  /** A steward moves the claim to the chosen person; a settled or voided claim cannot move. */
470	  protected async reassign(c: Claim): Promise<void> {
471	    this.clearRowError(c.id);
472	    const sheet = this.session.sheetId();
473	    if (!sheet) return;
474	    const to = this.reassignTo()[c.id] ?? '';
475	    if (!to) {
476	      this.setRowError(c.id, 'Choose the person to move this claim to.');
477	      return;
478	    }
479	    if (c.status === 'SETTLED' || c.status === 'VOID') {
480	      this.setRowError(c.id, `A ${c.status} claim cannot move.`);
481	      return;
482	    }
483	    if (inClosedPeriod(this.periods.list(), c.date)) {
484	      this.setRowError(c.id, CLOSED);
485	      return;
486	    }
487	    const url = `/api/sheets/${encodeURIComponent(sheet)}/claims/${c.id}/reassign`;
488	    try {
489	      const moved = await firstValueFrom(this.http.post<Claim>(url, { personId: Number(to) }));
490	      this.reassignTo.update(({ [c.id]: _, ...rest }) => rest);
491	      this.saved.emit(moved);
492	    } catch (e) {
493	      const forbidden = e instanceof HttpErrorResponse && e.status === 403;
494	      this.setRowError(
495	        c.id,
496	        forbidden ? 'Only a steward can move a claim.' : `This ${c.status} claim cannot be moved to that person.`,
497	      );
498	    }
499	  }

